INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '最高気温と最低気温の差が最も大きい月の気温は、差が最も小さい月の気温の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.93倍", "3.14倍", "1.91倍", "2.64倍", "3.44倍"]', 3, '["差が最も大きいのは8月（30.4－15.5＝14.9）、最も小さいのは3月（11.5－2.4＝9.1）。8月の気温30.4と3月の気温11.5を比べる。30.4÷11.5＝2.643… 答えは約2.64倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '売上高と経費の差が最も大きい月の売上高は、差が最も小さい月の売上高の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.20倍", "2.86倍", "1.73倍", "2.46倍", "2.68倍"]', 0, '["差が最も大きいのは7月（77－51＝26）、最も小さいのは1月（35－27＝8）。7月の売上高77と1月の売上高35を比べる。77÷35＝2.200… 答えは約2.20倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '休日来場者数と平日来場者数の差が最も大きい月の休日来場者数は、差が最も小さい月の休日来場者数の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["3.69倍", "3.23倍", "2.33倍", "2.93倍", "2.05倍"]', 3, '["差が最も大きいのは6月（16.1－7.2＝8.9）、最も小さいのは1月（5.5－3.8＝1.7）。6月の休日来場者数16.1と1月の休日来場者数5.5を比べる。16.1÷5.5＝2.927… 答えは約2.93倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
