INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '生産数と不良品数の差が最も大きい月の生産数は、差が最も小さい月の生産数の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.33倍", "1.05倍", "1.19倍", "1.66倍", "0.96倍"]', 0, '["差が最も大きいのは7月（1085－97＝988）、最も小さいのは1月（815－36＝779）。7月の生産数1085と1月の生産数815を比べる。1085÷815＝1.331… 答えは約1.33倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '降水量と蒸発量の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["7.73倍", "6.85倍", "4.32倍", "6.06倍", "5.27倍"]', 3, '["各月の降水量と蒸発量の差を求めると、最も大きいのは7月の172－63＝109mm、最も小さいのは1月の47－29＝18mm。109÷18＝6.056… 答えは約6.06倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', 'スマホ閲覧数とPC閲覧数の差が最も大きい月のスマホ閲覧数は、差が最も小さい月のスマホ閲覧数の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.54倍", "2.46倍", "2.76倍", "1.75倍", "2.16倍"]', 4, '["差が最も大きいのは8月（56.3－22.1＝34.2）、最も小さいのは1月（26.1－13.0＝13.1）。8月のスマホ閲覧数56.3と1月のスマホ閲覧数26.1を比べる。56.3÷26.1＝2.157… 答えは約2.16倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '最高気温と最低気温の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.43倍", "1.72倍", "2.04倍", "1.29倍", "2.23倍"]', 1, '["各月の最高気温と最低気温の差を求めると、最も大きいのは6月の29.7－14.7＝15.0℃、最も小さいのは11月の10.3－1.6＝8.7℃。15.0÷8.7＝1.724… 答えは約1.72倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、青空大学の授業形態別受講比率を2016年と2022年で示したものである。対面授業の人数は、2016年から2022年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.03倍", "1.82倍", "1.41倍", "1.22倍", "1.59倍"]', 4, '["2016年の対面授業＝5,900人×46%＝2,714.00人。2022年の対面授業＝7,700人×56%＝4,312.00人。4,312.00÷2,714.00＝1.589… 答えは約1.59倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、風見量販店の家電カテゴリ別販売台数を2017年と2023年で示したものである。一般家電の台数は、2017年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.29倍", "1.48倍", "1.79倍", "1.33倍", "2.15倍"]', 2, '["2017年の一般家電＝29万台×54%＝15.66万台。2023年の一般家電＝56万台×50%＝28.00万台。28.00÷15.66＝1.788… 答えは約1.79倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、西原サービスの利用者年代構成を2017年と2023年で示したものである。20代以下の人数は、2017年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["6.68倍", "4.86倍", "5.34倍", "8.13倍", "7.61倍"]', 0, '["2017年の20代以下＝24万人×15%＝3.60万人。2023年の20代以下＝65万人×37%＝24.05万人。24.05÷3.60＝6.681… 答えは約6.68倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、南風国の輸出額の内訳を2016年と2022年で示したものである。有機農産物の額は、2016年から2022年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["3.49倍", "2.72倍", "2.17倍", "3.27倍", "1.94倍"]', 1, '["2016年の有機農産物＝138億円×14%＝19.32億円。2022年の有機農産物＝202億円×26%＝52.52億円。52.52÷19.32＝2.718… 答えは約2.72倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
