INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、結ヶ丘大学の授業形態別受講比率を2016年と2022年で示したものである。対面授業の人数は、2016年から2022年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.50倍", "2.12倍", "1.21倍", "1.86倍", "1.69倍"]', 4, '["2016年の対面授業＝4,900人×50%＝2,450.00人。2022年の対面授業＝7,000人×59%＝4,130.00人。4,130.00÷2,450.00＝1.686… 答えは約1.69倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、湊量販店の家電カテゴリ別販売台数を2017年と2023年で示したものである。一般家電の台数は、2017年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.42倍", "2.78倍", "1.87倍", "3.09倍", "2.13倍"]', 0, '["2017年の一般家電＝42万台×40%＝16.80万台。2023年の一般家電＝74万台×55%＝40.70万台。40.70÷16.80＝2.423… 答えは約2.42倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、中央家の月間食費内訳（総額160,000円）を示したものである。食材費にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["49,600円", "62,869円", "43,447円", "58,652円", "55,158円"]', 0, '["総額160,000円のうち食材費は31%を占めるので、160,000×0.31＝49,600円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、水明大学生協の書籍販売額内訳（総額560,000円）を示したものである。漫画にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["35,288円", "54,099円", "44,800円", "49,908円", "40,525円"]', 2, '["総額560,000円のうち漫画は8%を占めるので、560,000×0.08＝44,800円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、花水木社従業員の通勤手段構成（総数1,160人）を示したものである。自動車にあてられている人数として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["154人", "208人", "220人", "141人", "174人"]', 4, '["総数1,160人のうち自動車は15%を占めるので、1,160×0.15＝174人。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、千歳フェスティバル来場者の年代別構成（総数4,540人）を示したものである。40代にあてられている人数として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["809人", "1,337人", "1,090人", "1,208人", "967人"]', 2, '["総数4,540人のうち40代は24%を占めるので、4,540×0.24＝1,090人。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、北斗社の月間販促費内訳（総額1,710,000円）を示したものである。広告費にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["185,813円", "169,290円", "205,200円", "251,192円", "234,970円"]', 2, '["総額1,710,000円のうち広告費は12%を占めるので、1,710,000×0.12＝205,200円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、若葉基金の収入源内訳（総額2,600万円）を示したものである。寄付にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["687万円", "916万円", "754万円", "551万円", "862万円"]', 2, '["総額2,600万円のうち寄付は29%を占めるので、2,600×0.29＝754万円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、星野家の月間食費内訳（総額95,000円）を示したものである。飲料費にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["30,400円", "37,508円", "27,611円", "23,707円", "33,531円"]', 0, '["総額95,000円のうち飲料費は32%を占めるので、95,000×0.32＝30,400円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、晴海市の予算内訳を2020年度と2023年度で示したものである。教育の金額は2020年度から2023年度でおよそいくら減少したか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["約7億円減少", "約9億円減少", "約6億円減少", "約8億円減少", "約5億円減少"]', 0, '["2020年度の教育＝52億円×23%＝12億円。2023年度の教育＝46億円×11%＝5億円。減少額＝7億円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、緑風社の事業別売上構成を2020年度と2023年度で示したものである。事業Bの金額は2020年度から2023年度でおよそいくら減少したか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["約1,041万円減少", "約1,264万円減少", "約1,663万円減少", "約929万円減少", "約1,475万円減少"]', 1, '["2020年度の事業B＝8,900万円×24%＝2,136万円。2023年度の事業B＝10,900万円×8%＝872万円。減少額＝1,264万円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、彩大学の系統別入学者数を2020年度と2023年度で示したものである。その他の人数は2020年度から2023年度でおよそいくら増加したか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["約44人増加", "約76人増加", "約58人増加", "約52人増加", "約67人増加"]', 2, '["2020年度のその他＝1,487人×13%＝193人。2023年度のその他＝1,479人×17%＝251人。増加額＝58人。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part4、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
